import type { DigitalPlatform } from './digital-platform-model';
import type { ManufacturingSite } from './manufacturing-site-model';

export const PortfolioInitiativeStatusKeyToLabel = {
  'OnTrack': 'On Track',
  'AtRisk': 'At Risk',
  'Delayed': 'Delayed'
} as const;
export type PortfolioInitiativeStatusKey = keyof typeof PortfolioInitiativeStatusKeyToLabel;

export interface PortfolioInitiative {
  /**
   * @displayName Portfolio Initiative ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Portfolio Initiative Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  portfolioInitiativeName: string;
  /**
   * @displayName Digital Platform
   * @validationRule Required for create/update operations
   */
  digitalPlatform: Pick<DigitalPlatform, 'id' | 'digitalPlatformName'>;
  /**
   * @displayName Executive Summary
   */
  executiveSummary?: string;
  /**
   * @displayName Golden Thread
   */
  goldenThread?: string;
  /**
   * @displayName Initiative Code
   * @validationRule Required for create/update operations
   */
  initiativeCode: string;
  /**
   * @displayName Manufacturing Site
   * @validationRule Required for create/update operations
   */
  manufacturingSite: Pick<ManufacturingSite, 'id' | 'siteName'>;
  /**
   * @displayName SPOT Number
   */
  sPOTNumber?: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: PortfolioInitiativeStatusKey;
  /**
   * @displayName Target Date
   */
  targetDate?: string;
}

export const _PortfolioInitiative = 'PortfolioInitiative' as const;